const headers = $input.first().json.headers || {};
// Try to find the header regardless of capitalization
const authHeader = headers['authorization'] || headers['Authorization'] || '';

if (!authHeader) {
  throw new Error('No Authorization header sent from browser.');
}

const token = authHeader.replace('Bearer ', '').trim();

if (!token || token === 'null' || token === 'undefined') {
  throw new Error('Token received was empty or the string "null". Check localStorage.');
}

// This regex matches: token_ (digits) _ (digits)
const match = token.match(/^token_(\d+)_(\d+)$/);

if (!match) {
  // This will tell you exactly what the token looked like in the error message
  throw new Error(`Token format invalid. Starts with: ${token.substring(0, 10)}...`);
}

const requesterId = parseInt(match[1], 10);
const body = $input.first().json.body || {};
const rawSearch = (body.query || '').toString().trim();

return [{ json: { requesterId, rawSearch } }];

const items = $input.all();
const grouped = { contacts: [], deals: [], companies: [], totalMatches: 0 };

for (const item of items) {
  const row = item.json;
  if (!row || !row.id) continue; // Skip empty results from alwaysOutputData

  const resultItem = {
    id: row.id,
    title: row.title || 'No Name',
    subtitle: row.subtitle || '',
    tag: row.tag || '',
    company: row.company || ''
  };

  const entityType = row.entity_type || 'contact';
  if (entityType === 'contact') grouped.contacts.push(resultItem);
  grouped.totalMatches++;
}

return [{ json: grouped }];
